            '2026-11-20', 'Approved', '/os/gif/decisions/GIF-DEC-041', 'Internal')
    returning id into v_od;
    values (v_prj, 'GIF-DEC-041', 'Programme pathways and places', 'Programme pathways and places?', 'Recorded before this workspace existed.', 'Baseline for everything else.', 'Fully Funded 10 places (competitive); Partial Funded 10 places as an outcome of the Fully Funded selection; Self-Funded direct admission subject to capacity; Project Mentoring as a separate paid track.', 'Founder decision sheet 20 Nov 2026 (docs/gif-platform/DECISIONS.md); Founder direction 21 Nov 2026 (docs/gif-platform/IELSCO-INTEGRATION.md)', '[]'::jsonb, null, null, null, null, null, 'Medium', 'Initial planning', null, null, (select id from public.os_people where id = 'PPL-0001'), 'Decided', 370, 'Fully Funded 10 places (competitive); Partial Funded 10 places as an outcome of the Fully Funded selection; Self-Funded direct admission subject to capacity; Project Mentoring as a separate paid track.', 'Founder decision on record: Founder decision sheet 20 Nov 2026 (docs/gif-platform/DECISIONS.md); Founder direction 21 Nov 2026 (docs/gif-platform/IELSCO-INTEGRATION.md)', '2026-11-20', v_od);
