  insert into public.os_programme_facts (project_id, key, label, category, value, unit, status, public_facing, source, source_decision, notes, sort) values (v_prj, 'insurance.requirement', 'Travel insurance', 'Safeguarding', 'Required for every participant; minimum cover awaiting approval', null, 'Pending', true, 'Site /program; DECISIONS.md open item 5', null, 'GIF-DEC-008', 600) on conflict (project_id, key) do nothing;
  insert into public.os_programme_facts (project_id, key, label, category, value, unit, status, public_facing, source, source_decision, notes, sort) values (v_prj, 'visa.policy', 'Visa support', 'Safeguarding', 'Participants are responsible for visas; IELSco provides supporting documents', null, 'Proposed', true, 'Site /program and Travel & Visa Disclaimer (draft)', null, 'GIF-DEC-035', 610) on conflict (project_id, key) do nothing;
  insert into public.os_programme_facts (project_id, key, label, category, value, unit, status, public_facing, source, source_decision, notes, sort) values (v_prj, 'scenario.low.self_funded', 'Planning scenario LOW: Self-Funded participants', 'Planning scenarios', '20', 'participants', 'Estimated', false, 'Planning assumption for the budget model, not a target or forecast', null, 'Change in the workspace; GIF-DEC-005 sets the real threshold.', 620) on conflict (project_id, key) do nothing;
  insert into public.os_programme_facts (project_id, key, label, category, value, unit, status, public_facing, source, source_decision, notes, sort) values (v_prj, 'scenario.base.self_funded', 'Planning scenario BASE: Self-Funded participants', 'Planning scenarios', '50', 'participants', 'Estimated', false, 'Planning assumption, not a target or forecast', null, null, 630) on conflict (project_id, key) do nothing;
  insert into public.os_programme_facts (project_id, key, label, category, value, unit, status, public_facing, source, source_decision, notes, sort) values (v_prj, 'scenario.high.self_funded', 'Planning scenario HIGH: Self-Funded participants', 'Planning scenarios', '80', 'participants', 'Estimated', false, 'Planning assumption: capacity 100 minus 20 funded places', null, null, 640) on conflict (project_id, key) do nothing;
  insert into public.os_programme_facts (project_id, key, label, category, value, unit, status, public_facing, source, source_decision, notes, sort) values (v_prj, 'scenario.mentoring', 'Planning scenario: Project Mentoring sign-ups', 'Planning scenarios', '40', 'participants', 'Estimated', false, 'Planning assumption, not a target or forecast', null, null, 650) on conflict (project_id, key) do nothing;
  insert into public.os_programme_facts (project_id, key, label, category, value, unit, status, public_facing, source, source_decision, notes, sort) values (v_prj, 'fx.usd_idr_card', 'Card payment rate', 'Planning scenarios', '18500', 'IDR per USD', 'Decided', false, 'PAYMENTS.md (fixed operational rate)', null, null, 660) on conflict (project_id, key) do nothing;
  insert into public.os_programme_decisions (project_id, code, title, question, background, why_it_matters, current_situation, evidence, options, recommended_option, recommendation, info_needed, delay_consequence, dependencies, priority, phase, suggested_deadline, deadline_basis, owner_person_id, status, sort) values (v_prj, 'GIF-DEC-001', 'Confirm the Self-Funded deposit amount', 'Is the Self-Funded deposit USD 300 / IDR 5,000,000, or another amount?', 'Registration and payments for Self-Funded opened on 20 Nov 2026. The GIF engine charges a deposit of USD 300 / IDR 5,000,000, carried over from the original programme brief. The founder sheet of 20 Nov asked to keep the deposit configurable and not to invent one, and it was never re-confirmed against the new USD 899 / IDR 14,999,000 fee.', 'Every Self-Funded registration now creates a deposit obligation with this amount. Changing it later means different terms for early and late registrants, refunds of differences, and edits to the Payment Terms, emails and receipts.', 'Live in production with 3 applications on 21 Nov 2026 (aggregate count from gif.applications). PRJ-0033 also has an open task ''Secure USD 1,500 participant deposits'' (TSK-0113), which matches neither figure.', null, '[{"key": "A", "label": "Confirm USD 300 / IDR 5,000,000", "summary": "Keep the live amount (about 33% of the fee).", "pros": "No change for people who already registered; nothing to redeploy.", "cons": "Cash collected early may not cover vendor deposits if they are large.", "cost": "None", "operations": "None", "participant": "Same terms for everyone.", "fact_updates": {"prices.deposit": "USD 300 / IDR 5,000,000"}}, {"key": "B", "label": "Set a different fixed amount", "summary": "Choose an amount that matches expected vendor deposits.", "pros": "Can match cash-flow needs once quotes exist.", "cons": "Quotes don''t exist yet; early registrants have different terms; needs settings change, legal text and email updates.", "cost": "Unknown until quotes", "operations": "Settings change + legal update", "participant": "Possible confusion for early registrants.", "fact_updates": {}}, {"key": "C", "label": "Percentage of the fee", "summary": "e.g. a fixed share of the pathway fee.", "pros": "Scales if prices change.", "cons": "Engine stores fixed amounts per currency; needs code change.", "cost": "Development time", "operations": "Code change and tests", "participant": "Clear rule, odd-looking amounts.", "fact_updates": {}}]'::jsonb, 'A', 'Confirm A now. It is already live, it is roughly a third of the fee, and changing it after people have paid creates unequal terms. Revisit only if vendor deposit quotes (GIF-RES-015) show a cash gap, and then for new registrants only.', 'Vendor deposit terms for accommodation and coaches (GIF-RES-015, GIF-RES-016).', 'Every new registration is charged an amount the founders have not confirmed; the Payment Terms stay bracketed.', 'Research: GIF-RES-015; Tasks: GIF-T-012, GIF-T-016', 'Critical', 'Research and decision-making', '2026-11-28', 'Payments are live; each day adds registrants under unconfirmed terms.', (select id from public.os_people where id = 'PPL-0001'), 'Pending Decision', 0) on conflict (code) do nothing;
  insert into public.os_programme_decisions (project_id, code, title, question, background, why_it_matters, current_situation, evidence, options, recommended_option, recommendation, info_needed, delay_consequence, dependencies, priority, phase, suggested_deadline, deadline_basis, owner_person_id, status, sort) values (v_prj, 'GIF-DEC-002', 'Choose the Malaysian city and host institution(s)', 'Which city in Malaysia does GIF visit, and which university engagement do we pursue there?', 'The plan of record (DOC-0054, 26 Oct 2026) routes Singapore → Johor Bahru (UTM) by land. The live website and the GIF engine settings list Universiti Malaya, which is in Kuala Lumpur. The founder brief lists both UM and UTM as potential destinations. UTM also has a Kuala Lumpur campus.', 'The city decides the transport legs, accommodation, the Malaysia country plan, the partner outreach list and what the website says.', 'Not decided. Website already names Universiti Malaya as ''planned''.', 'DOC-0054 §2 (Johor Bahru/UTM) vs apps/gif settings universities[] (Universiti Malaya) and gif.ielsco.com/program.', '[{"key": "A", "label": "Kuala Lumpur: Universiti Malaya", "summary": "Coach Singapore → KL, fly KL → Bangkok.", "pros": "Matches the website; many KL–Bangkok flights; large student community and Indonesian student association.", "cons": "Long coach day from Singapore (border plus several hours).", "cost": "Coach day + KL accommodation", "operations": "One long transfer day", "participant": "Capital-city experience; tiring transfer day.", "fact_updates": {"route.malaysia_city": "Kuala Lumpur (Universiti Malaya)"}}, {"key": "B", "label": "Johor Bahru: UTM Johor Bahru", "summary": "Short land crossing from Singapore; fly from Johor Bahru or KL to Bangkok.", "pros": "Short cross-border leg; DOC-0054 baseline.", "cons": "Website must change (it names UM); onward flights from Johor Bahru are fewer.", "cost": "Lower coach cost; flight options to verify", "operations": "Short transfer", "participant": "Less time on the road.", "fact_updates": {"route.malaysia_city": "Johor Bahru (UTM Johor Bahru)"}}, {"key": "C", "label": "Kuala Lumpur with UM and UTM Kuala Lumpur", "summary": "As A, approaching both universities in KL.", "pros": "Two chances of a confirmed host in one city.", "cons": "More outreach work for Shafira.", "cost": "As A", "operations": "As A", "participant": "As A", "fact_updates": {"route.malaysia_city": "Kuala Lumpur (Universiti Malaya and UTM Kuala Lumpur)"}}]'::jsonb, 'C', 'Provisionally C: Kuala Lumpur, approaching both Universiti Malaya and UTM''s Kuala Lumpur campus. It keeps the website accurate and gives two chances of a confirmed host. Confirm only after GIF-RES-005 (transfer times and coach operators) and the first replies from both universities.', 'Singapore → KL and KL/JB → Bangkok transfer times and costs (GIF-RES-005, GIF-RES-006); first responses from UM and UTM (GIF-T-041).', 'Outreach, accommodation research and the itinerary can''t start for Malaysia; the website keeps naming one university that may not be the host.', 'Research: GIF-RES-005, GIF-RES-006; Tasks: GIF-T-008, GIF-T-041, GIF-T-060, GIF-T-061', 'Critical', 'Research and decision-making', '2026-12-18', 'Partner outreach starts in January (TL-021/022 in the old plan); accommodation research needs the city.', (select id from public.os_people where id = 'PPL-0002'), 'Needs Research', 10) on conflict (code) do nothing;
  insert into public.os_programme_decisions (project_id, code, title, question, background, why_it_matters, current_situation, evidence, options, recommended_option, recommendation, info_needed, delay_consequence, dependencies, priority, phase, suggested_deadline, deadline_basis, owner_person_id, status, sort) values (v_prj, 'GIF-DEC-003', 'Choose how the group travels between countries', 'How do participants move Singapore → Malaysia and Malaysia → Thailand?', 'DOC-0054 assessed three routes: full land (about one day and night of travel to Bangkok with a second border; not recommended for a short programme), land plus one flight (recommended), and two countries only (fallback).', 'Transport is one of the largest cost lines and the biggest safety and delay risk. It decides luggage rules, the arrival card and border procedures participants must prepare for, and the day split.', 'Proposed in DOC-0054 (land + one flight); not decided.', null, '[{"key": "A", "label": "Chartered coach to Malaysia, flight to Bangkok", "summary": "Licensed cross-border coach, then a group booking on a flight.", "pros": "One border by road with the group together; protects programme days.", "cons": "Flight cost and baggage fees per participant; group-fare terms.", "cost": "Coach charter + ~100 flight seats (quotes needed)", "operations": "Group check-in, baggage manifest", "participant": "Short Thailand transfer.", "fact_updates": {"route.transport_modes": "Chartered coach Singapore → Malaysia; flight Malaysia → Bangkok"}}, {"key": "B", "label": "Land all the way", "summary": "Coach/rail through to Bangkok.", "pros": "Lower ticket cost; ''overland'' experience.", "cons": "Roughly a day of travel and a second land border; fatigue and delay risk; loses a programme day.", "cost": "Lower tickets, extra night", "operations": "Long day with minors", "participant": "Very tiring.", "fact_updates": {}}, {"key": "C", "label": "Fly both legs", "summary": "Fly Singapore → Malaysia and Malaysia → Bangkok.", "pros": "Fastest.", "cons": "Two group check-ins; more cost; loses the land-border experience.", "cost": "Highest", "operations": "Two airport days", "participant": "Short but airport-heavy.", "fact_updates": {}}]'::jsonb, 'A', 'A: chartered coach into Malaysia and one flight to Bangkok. It is DOC-0054''s assessed baseline and keeps everyone together across the land border. Get coach and group-fare quotes before G2.', 'Coach operator licensing for cross-border groups, border processing for coaches, group fares and baggage (GIF-RES-005, GIF-RES-006, GIF-RES-007).', 'No transport quotes, so no budget; group fares get scarcer for late-July travel.', 'Research: GIF-RES-005, GIF-RES-006, GIF-RES-007; Tasks: GIF-T-060, GIF-T-061, GIF-T-062', 'Critical', 'Research and decision-making', '2026-12-18', 'Needed before transport quotes (GIF-T-061) and the budget gate.', (select id from public.os_people where id = 'PPL-0002'), 'Pending Decision', 20) on conflict (code) do nothing;
  insert into public.os_programme_decisions (project_id, code, title, question, background, why_it_matters, current_situation, evidence, options, recommended_option, recommendation, info_needed, delay_consequence, dependencies, priority, phase, suggested_deadline, deadline_basis, owner_person_id, status, sort) values (v_prj, 'GIF-DEC-004', 'Split the 8 days across the three countries', 'How many days and nights in Singapore, Malaysia and Thailand, and where do arrival and departure fall?', '27 Jul – 3 Aug is 8 days and 7 nights. The site says flights are to Singapore and from Thailand. Conference, competition and awarding days are not yet placed.', 'Decides accommodation nights per city, venue needs, run sheets, staff rotation and where the conference and awarding happen.', 'Not decided.', null, '[{"key": "A", "label": "3 / 2 / 3", "summary": "Singapore 3 nights, Malaysia 2, Thailand 2 + departure day.", "pros": "Arrival buffer in Singapore; awarding in Bangkok at the end.", "cons": "Short Malaysia stay.", "cost": "", "operations": "", "participant": "", "fact_updates": {"route.day_split": "Singapore 3 nights · Malaysia 2 nights · Thailand 2 nights; departure from Bangkok on 3 Aug"}}, {"key": "B", "label": "2 / 3 / 2", "summary": "Singapore 2 nights, Malaysia 3, Thailand 2.", "pros": "Lower Singapore accommodation cost (usually the most expensive city).", "cons": "Less arrival buffer.", "cost": "", "operations": "", "participant": "", "fact_updates": {"route.day_split": "Singapore 2 nights · Malaysia 3 nights · Thailand 2 nights; departure from Bangkok on 3 Aug"}}, {"key": "C", "label": "Decide after partner replies", "summary": "Hold until hosts confirm dates.", "pros": "Fits host availability.", "cons": "Delays itinerary, budget and bookings.", "cost": "", "operations": "", "participant": "", "fact_updates": {}}]'::jsonb, 'B', 'Provisionally B (2 / 3 / 2) to reduce the most expensive accommodation nights, but confirm only after the first host replies and accommodation quotes (GIF-RES-008). Put the conference and awarding in the final country so travel days don''t cut into them.', 'Accommodation prices per city for late July (GIF-RES-008); host availability (GIF-T-041).', 'Itinerary, budget and venue research stay blocked; the website cannot show an itinerary on 8 Jun as promised.', 'Research: GIF-RES-008; Tasks: GIF-T-050, GIF-T-063', 'High', 'Programme design', '2027-01-15', 'Itinerary and budget scenarios (G2, 9 Apr) need it; outreach letters need proposed dates.', (select id from public.os_people where id = 'PPL-0002'), 'Pending Decision', 30) on conflict (code) do nothing;
  insert into public.os_programme_decisions (project_id, code, title, question, background, why_it_matters, current_situation, evidence, options, recommended_option, recommendation, info_needed, delay_consequence, dependencies, priority, phase, suggested_deadline, deadline_basis, owner_person_id, status, sort) values (v_prj, 'GIF-DEC-005', 'Set participant capacity and the minimum viable cohort', 'What is the maximum cohort, and below how many paying participants do we not run (or reduce scope)?', 'The GIF engine has capacity 100 (cohort setting). The founder sheet decided 10 Fully Funded and 10 Partial Funded places but not total capacity or a minimum. Eight core staff travel.', 'Capacity drives staff-to-participant ratios, coach and room blocks, venue sizes and the break-even point. The minimum protects against running at a loss.', 'Capacity 100 is live in settings (status: proposed). No minimum.', null, '[{"key": "A", "label": "Keep 100 and set a minimum at break-even", "summary": "Minimum = paying participants needed to cover fixed costs (from the budget model).", "pros": "Uses the model; protects cash.", "cons": "Needs quotes first.", "cost": "", "operations": "Ratio 1:12 with 8 staff before local support", "participant": "", "fact_updates": {"capacity.total": "100"}}, {"key": "B", "label": "Reduce capacity to 60", "summary": "Smaller, easier to run with 8 staff.", "pros": "Lower risk, one coach.", "cons": "Less revenue; Self-Funded closes earlier.", "cost": "", "operations": "1:7.5 with 8 staff", "participant": "", "fact_updates": {"capacity.total": "60"}}, {"key": "C", "label": "Capacity by bookings", "summary": "Grow capacity in steps as room/coach blocks are confirmed.", "pros": "Never oversells logistics.", "cons": "More admin.", "cost": "", "operations": "", "participant": "", "fact_updates": {}}]'::jsonb, 'A', 'A: keep 100 as the ceiling and set the minimum viable cohort from the budget model once quotes exist (target by 9 Apr, G2). With 8 core staff, plan local support so no core member supervises more than one group alone.', 'Fixed costs from quotes (GIF-BUD lines); supervision ratio for minors (GIF-DEC-007).', 'Recruitment marketing can''t state places; no go/no-go threshold for commitments.', 'Tasks: GIF-T-017, GIF-T-018', 'High', 'Financial preparation', '2027-01-31', 'Must exist before vendor deposits (G4) and should guide marketing intensity.', (select id from public.os_people where id = 'PPL-0001'), 'Pending Decision', 40) on conflict (code) do nothing;
  insert into public.os_programme_decisions (project_id, code, title, question, background, why_it_matters, current_situation, evidence, options, recommended_option, recommendation, info_needed, delay_consequence, dependencies, priority, phase, suggested_deadline, deadline_basis, owner_person_id, status, sort) values (v_prj, 'GIF-DEC-006', 'Decide how the 8 core team members'' travel is funded', 'Does the GIF budget pay the core team''s flights, accommodation and costs, and what exactly does the managers'' ''fully funded'' benefit include?', 'The six manager agreements include ''GIF Summer 2027 Program, fully funded, three countries (details in the Program Confirmation)''. The Program Confirmation does not exist yet. Participants'' Fully Funded award excludes international flights.', 'Eight staff travel costs are a large fixed cost and a contractual promise. The Program Confirmation must say what is covered.', 'Benefit promised in draft agreements; scope undefined.', null, '[{"key": "A", "label": "Programme pays everything for all 8", "summary": "Flights, accommodation, transport, meals, insurance.", "pros": "Clear and fair; staff are working.", "cons": "Highest fixed cost.", "cost": "8 × full travel cost", "operations": "", "participant": "", "fact_updates": {}}, {"key": "B", "label": "Same as a Fully Funded participant, plus flights for staff on duty", "summary": "Managers'' benefit mirrors Fully Funded; flights covered as a work cost.", "pros": "Consistent with participant award wording.", "cons": "Need a clear ''on duty'' definition.", "cost": "", "operations": "", "participant": "", "fact_updates": {}}, {"key": "C", "label": "Same as Fully Funded participants (no flights)", "summary": "Staff pay their own flights.", "pros": "Lowest cost.", "cons": "May conflict with ''fully funded'' in the agreements; staff are working.", "cost": "", "operations": "", "participant": "", "fact_updates": {}}]'::jsonb, 'B', 'B: treat the 8 as working staff. Cover in-programme costs like a Fully Funded participant, and pay flights as a work cost. Write it into the Program Confirmation (GIF-OUT-038) and have counsel check it against the agreement wording.', 'Flight estimates (GIF-RES-006); counsel''s reading of ''fully funded'' in the agreements.', 'Budget stays incomplete; managers sign agreements with an undefined benefit.', 'Research: GIF-RES-006; Tasks: GIF-T-019, GIF-T-031', 'High', 'Financial preparation', '2027-01-31', 'Before agreements are signed and before the budget gate.', (select id from public.os_people where id = 'PPL-0001'), 'Pending Decision', 50) on conflict (code) do nothing;
  insert into public.os_programme_decisions (project_id, code, title, question, background, why_it_matters, current_situation, evidence, options, recommended_option, recommendation, info_needed, delay_consequence, dependencies, priority, phase, suggested_deadline, deadline_basis, owner_person_id, status, sort) values (v_prj, 'GIF-DEC-007', 'Set the operating rules for under-18 participants', 'Do we accept participants under 18, from what age, and with which supervision, rooming and curfew rules?', 'The audience includes high school students. Guardian consent is built into the platform and blocks payment until recorded (decided 20 Nov). Supervision ratio, rooming, curfew, chaperones and emergency procedures for minors are not set (DECISIONS.md open item 4). Legal text says they will be shared before departure.', 'Safeguarding is the highest-impact risk area. Rules decide staff ratios, rooms, volunteer roles, insurance and what parents are promised.', 'Minors can apply and register now with guardian consent. No operating rules.', null, '[{"key": "A", "label": "Accept 15–17 with strict rules", "summary": "Minimum age 15; separate rooming by gender and age band; curfew; no minor alone with any adult; designated safeguarding lead; ratio set from research.", "pros": "Keeps the high school audience; rules are explicit.", "cons": "More staff/volunteer coverage; more paperwork.", "cost": "Possibly more rooms", "operations": "Yasmine as safeguarding lead", "participant": "Parents get clear rules.", "fact_updates": {"minors.operations": "Accepted from age 15 with separate rooming, curfew, two-adult rule and a designated safeguarding lead; ratio to be set"}}, {"key": "B", "label": "Accept minors only with a parent or school chaperone", "summary": "Under-18s must travel with an adult chaperone.", "pros": "Lower duty of care on IELSco.", "cons": "Fewer high school participants; chaperone costs.", "cost": "", "operations": "", "participant": "", "fact_updates": {}}, {"key": "C", "label": "18+ only", "summary": "Change the audience to 18+.", "pros": "Simplest safeguarding.", "cons": "Contradicts the brief and live marketing; needs website and terms changes.", "cost": "", "operations": "", "participant": "", "fact_updates": {}}]'::jsonb, 'A', 'A, with the ratio and age floor confirmed after GIF-RES-012 (safeguarding standards) and GIF-RES-013 (rules for minors travelling without parents in each country).', 'GIF-RES-012, GIF-RES-013; insurer conditions for minors (GIF-RES-010).', 'Minors are registering now without published rules; safeguarding policy and parent pack can''t be written.', 'Research: GIF-RES-012, GIF-RES-013; Tasks: GIF-T-033, GIF-T-034, GIF-T-087', 'Critical', 'Research and decision-making', '2026-12-15', 'High school recruitment is open; parents will ask before paying.', (select id from public.os_people where id = 'PPL-0002'), 'Needs Research', 60) on conflict (code) do nothing;
  insert into public.os_programme_decisions (project_id, code, title, question, background, why_it_matters, current_situation, evidence, options, recommended_option, recommendation, info_needed, delay_consequence, dependencies, priority, phase, suggested_deadline, deadline_basis, owner_person_id, status, sort) values (v_prj, 'GIF-DEC-008', 'Decide the travel insurance arrangement', 'Does each participant buy their own travel insurance with a minimum cover, or does IELSco arrange a group policy?', 'The site says travel and health insurance covering the whole programme is required. Minimum cover is ''awaiting approval'' (DECISIONS.md open item 5).', 'Medical emergencies abroad are expensive. A gap in cover becomes IELSco''s problem on site.', 'Required; no minimum, no provider.', null, '[{"key": "A", "label": "Group policy arranged by IELSco", "summary": "One insurer for everyone; cost included or added.", "pros": "Uniform cover; one assistance line.", "cons": "IELSco admin; price per person; may not fit international participants.", "cost": "Per-person premium (quote)", "operations": "One policy schedule", "participant": "Simple for families.", "fact_updates": {}}, {"key": "B", "label": "Participant buys own policy meeting a minimum", "summary": "IELSco sets minimum medical, evacuation and cancellation cover and checks certificates.", "pros": "No premium cost to IELSco.", "cons": "Checking documents; varying claims processes.", "cost": "None", "operations": "Document checks before G5", "participant": "More work for families.", "fact_updates": {}}, {"key": "C", "label": "Group policy for Indonesians, own policy for international participants", "summary": "Hybrid.", "pros": "Fits both audiences.", "cons": "Two processes.", "cost": "", "operations": "", "participant": "", "fact_updates": {}}]'::jsonb, 'C', 'Provisionally C, pending quotes (GIF-RES-010). Set the minimum cover with the insurer''s advice, and apply it to staff too.', 'Quotes and coverage terms from at least two insurers (GIF-RES-010).', 'Legal text stays bracketed; risk of uninsured participants.', 'Research: GIF-RES-010; Tasks: GIF-T-035', 'High', 'Research and decision-making', '2027-02-26', 'Insurance terms must be in the participant handbook and terms before results (1 Jun).', (select id from public.os_people where id = 'PPL-0001'), 'Pending Decision', 70) on conflict (code) do nothing;
  insert into public.os_programme_decisions (project_id, code, title, question, background, why_it_matters, current_situation, evidence, options, recommended_option, recommendation, info_needed, delay_consequence, dependencies, priority, phase, suggested_deadline, deadline_basis, owner_person_id, status, sort) values (v_prj, 'GIF-DEC-009', 'Retire the outdated GIF timeline rows and plan dates', 'Do we mark the old 5–11 July GIF plan (DOC-0054 and the Master Timeline rows) as superseded?', 'DOC-0054 and 52 Master Timeline items (TL-020 to TL-104 for GIF) were written for a 7-day programme on 5–11 Jul 2027 with applications opening 26 Apr 2027. The current baseline is 27 Jul – 3 Aug with recruitment since 20/25 Nov 2026. The new GIF milestones (WS10) are in the timeline alongside them.', 'Two GIF timelines in the same OS will mislead the team. The old rows show ''Not started'' tasks with dates that no longer apply.', 'Both exist. Nothing was deleted or changed.', null, '[{"key": "A", "label": "Mark old rows Cancelled with a pointer", "summary": "Set the old GIF rows to Cancelled with ''Superseded by WS10 (21 Nov 2026)''; mark DOC-0054 v0.1 superseded and keep it for the gate concept.", "pros": "One timeline; history kept.", "cons": "A one-off edit by a founder.", "cost": "", "operations": "", "participant": "", "fact_updates": {}}, {"key": "B", "label": "Update old rows in place", "summary": "Re-date the old rows instead of using WS10.", "pros": "Keeps TL ids.", "cons": "Mixes old structure with the new; many rows don''t map.", "cost": "", "operations": "", "participant": "", "fact_updates": {}}, {"key": "C", "label": "Leave both", "summary": "", "pros": "", "cons": "Confusing; double counting on Home and timeline.", "cost": "", "operations": "", "participant": "", "fact_updates": {}}]'::jsonb, 'A', 'A. Nothing is deleted: rows are kept, marked Cancelled with a pointer, and DOC-0054 is marked superseded on dates while its gate concept (G0–G5) carries over to GIF-DEC-040.', 'None.', 'The Home dashboard and the Timeline keep showing the wrong programme dates.', 'Tasks: GIF-T-003', 'Critical', 'Initial planning', '2026-11-28', 'Data hygiene; quick.', (select id from public.os_people where id = 'PPL-0002'), 'Pending Decision', 80) on conflict (code) do nothing;
  insert into public.os_programme_decisions (project_id, code, title, question, background, why_it_matters, current_situation, evidence, options, recommended_option, recommendation, info_needed, delay_consequence, dependencies, priority, phase, suggested_deadline, deadline_basis, owner_person_id, status, sort) values (v_prj, 'GIF-DEC-010', 'Align the launch events with the live recruitment dates', 'What do the ''GIF 2027 Open Pre-Launch'' (7 Dec) and ''Official Launch'' (9 Jan) calendar events mean now that registration opened 20 Nov and Fully Funded opens 25 Nov?', 'Calendar events EV-0032 and EV-0033 predate the 21 Nov registration timeline.', 'The marketing calendar, campaign content and announcements depend on one launch narrative.', 'Conflicting.', null, '[{"key": "A", "label": "Treat 25 Nov as launch; repurpose the events", "summary": "7 Dec becomes an info session; 9 Jan becomes a Fully Funded push / mentoring early-bird close follow-up.", "pros": "Matches the live platform.", "cons": "Event content needs rework.", "cost": "", "operations": "", "participant": "", "fact_updates": {}}, {"key": "B", "label": "Keep 9 Jan as the ''official'' public launch", "summary": "Soft-open now, big launch in January.", "pros": "More preparation time for content.", "cons": "Mixed messages to applicants already registering.", "cost": "", "operations": "", "participant": "", "fact_updates": {}}, {"key": "C", "label": "Cancel both events", "summary": "", "pros": "Less work.", "cons": "Loses awareness moments.", "cost": "", "operations": "", "participant": "", "fact_updates": {}}]'::jsonb, 'A', 'A: the platform is the truth. Repurpose both events into recruitment moments and update the campaign calendar.', 'Didi and Acha''s content plan.', 'Campaign content contradicts the platform dates.', 'Tasks: GIF-T-020', 'High', 'Recruitment preparation', '2026-11-28', 'The 7 Dec event is two weeks away.', (select id from public.os_people where id = 'PPL-0003'), 'Pending Decision', 90) on conflict (code) do nothing;
  insert into public.os_programme_decisions (project_id, code, title, question, background, why_it_matters, current_situation, evidence, options, recommended_option, recommendation, info_needed, delay_consequence, dependencies, priority, phase, suggested_deadline, deadline_basis, owner_person_id, status, sort) values (v_prj, 'GIF-DEC-011', 'Approve the eight-person responsibility model', 'Do you approve the proposed workstream owners and roles for the 8 travelling team members?', 'Proposed in this workspace (People tab) from os_people titles, DOC-0053 decision rights and the manager agreements (each manager at most 2 h/day, 10 h/week, remote before travel).', 'Every task owner and escalation route depends on it.', 'Proposed; tasks are pre-assigned on that basis and remain editable.', null, '[{"key": "A", "label": "Approve as proposed", "summary": "", "pros": "Work starts with clear owners.", "cons": "", "cost": "", "operations": "", "participant": "", "fact_updates": {}}, {"key": "B", "label": "Approve with changes", "summary": "Say which workstreams move.", "pros": "", "cons": "Tasks need reassigning.", "cost": "", "operations": "", "participant": "", "fact_updates": {}}, {"key": "C", "label": "Reject; propose again", "summary": "", "pros": "", "cons": "Delays every workstream.", "cost": "", "operations": "", "participant": "", "fact_updates": {}}]'::jsonb, 'A', 'A, with one caution: the six managers together have at most about 60 hours a week. Keep founders on decisions and approvals, and push execution to local support and vendors where the workspace marks it.', 'None.', 'Tasks have owners who haven''t agreed to them.', 'Tasks: GIF-T-002', 'Critical', 'Initial planning', '2026-11-30', 'Assignments start now.', (select id from public.os_people where id = 'PPL-0001'), 'Pending Decision', 100) on conflict (code) do nothing;
  insert into public.os_programme_decisions (project_id, code, title, question, background, why_it_matters, current_situation, evidence, options, recommended_option, recommendation, info_needed, delay_consequence, dependencies, priority, phase, suggested_deadline, deadline_basis, owner_person_id, status, sort) values (v_prj, 'GIF-DEC-012', 'Confirm decision rights between Arba and Farrel for GIF', 'Who approves what for GIF?', 'DOC-0053 (draft): Farrel accountable for GIF 2027; Arba approves every financial and legal commitment, public statement and paid spend. Both answer the programme decisions in this workspace.', 'Prevents double approvals and stalls.', 'Draft (DOC-0053 not approved).', null, '[{"key": "A", "label": "As DOC-0053", "summary": "Farrel: operations and programme delivery; Arba: money, legal, public statements, website/dashboard. Either may answer a decision in their area; Critical decisions need both.", "pros": "Clear.", "cons": "", "cost": "", "operations": "", "participant": "", "fact_updates": {}}, {"key": "B", "label": "Both approve everything", "summary": "", "pros": "Shared view.", "cons": "Slow.", "cost": "", "operations": "", "participant": "", "fact_updates": {}}, {"key": "C", "label": "Farrel approves all GIF; Arba only finance", "summary": "", "pros": "Fast.", "cons": "Public statements and legal exposure outside Arba.", "cost": "", "operations": "", "participant": "", "fact_updates": {}}]'::jsonb, 'A', 'A. The workspace records who answered each decision, so the split is auditable.', 'None.', 'Ambiguous approvals.', 'Tasks: GIF-T-001', 'Critical', 'Initial planning', '2026-11-30', 'Needed for the decision queue itself.', (select id from public.os_people where id = 'PPL-0001'), 'Pending Decision', 110) on conflict (code) do nothing;
  insert into public.os_programme_decisions (project_id, code, title, question, background, why_it_matters, current_situation, evidence, options, recommended_option, recommendation, info_needed, delay_consequence, dependencies, priority, phase, suggested_deadline, deadline_basis, owner_person_id, status, sort) values (v_prj, 'GIF-DEC-013', 'Set spend approval and procurement rules for GIF', 'Above what amount is Arba''s prior approval and more than one quote required?', 'No GIF budget, approval limits or procurement procedure is on record. Finance and legal are Restricted in the Company OS.', 'Vendor bookings start after G4; on-site cash spending needs a rule.', 'None.', null, '[{"key": "A", "label": "Every commitment pre-approved by Arba; two quotes above a threshold", "summary": "Threshold set by Arba; on-site petty cash float with receipts.", "pros": "Tight control.", "cons": "Arba as bottleneck on site.", "cost": "", "operations": "", "participant": "", "fact_updates": {}}, {"key": "B", "label": "Farrel approves within approved budget lines; Arba above a threshold", "summary": "", "pros": "Faster on site.", "cons": "Requires an approved budget first.", "cost": "", "operations": "", "participant": "", "fact_updates": {}}]'::jsonb, 'B', 'B once the budget is approved (G2); A until then. Arba sets the thresholds.', 'Approved budget.', 'Ad-hoc spending; reconciliation problems.', 'Tasks: GIF-T-014', 'High', 'Financial preparation', '2026-12-31', 'Before any vendor contact asks for deposits.', (select id from public.os_people where id = 'PPL-0001'), 'Pending Decision', 120) on conflict (code) do nothing;
  insert into public.os_programme_decisions (project_id, code, title, question, background, why_it_matters, current_situation, evidence, options, recommended_option, recommendation, info_needed, delay_consequence, dependencies, priority, phase, suggested_deadline, deadline_basis, owner_person_id, status, sort) values (v_prj, 'GIF-DEC-014', 'Set the budget envelope, contingency and break-even rule', 'What contingency reserve do we hold, and do we commit vendor deposits only when paid revenue covers fixed costs?', 'The budget model in this workspace computes revenue from decided prices and planning scenarios. Costs are not estimated yet (no quotes).', 'Protects IELSco from losses if recruitment is low.', 'No budget.', null, '[{"key": "A", "label": "10% contingency; commit only when paid revenue covers fixed costs", "summary": "", "pros": "", "cons": "", "cost": "", "operations": "", "participant": "", "fact_updates": {}}, {"key": "B", "label": "15% contingency; same commitment rule", "summary": "", "pros": "More buffer for FX and late changes.", "cons": "Higher break-even.", "cost": "", "operations": "", "participant": "", "fact_updates": {}}, {"key": "C", "label": "20% contingency", "summary": "", "pros": "Most buffer.", "cons": "Highest break-even.", "cost": "", "operations": "", "participant": "", "fact_updates": {}}]'::jsonb, 'B', 'B: 15%, because costs are in SGD, MYR and THB but revenue is in IDR/USD, and quotes for late July may rise. Commit vendor deposits only against verified paid revenue.', 'Quotes (GIF-RES-008, -015, -016).', 'No go/no-go rule for commitments.', 'Tasks: GIF-T-015', 'High', 'Financial preparation', '2027-02-26', 'Before G2 (budget gate).', (select id from public.os_people where id = 'PPL-0001'), 'Pending Decision', 130) on conflict (code) do nothing;
  insert into public.os_programme_decisions (project_id, code, title, question, background, why_it_matters, current_situation, evidence, options, recommended_option, recommendation, info_needed, delay_consequence, dependencies, priority, phase, suggested_deadline, deadline_basis, owner_person_id, status, sort) values (v_prj, 'GIF-DEC-015', 'Choose the accommodation standard and rooming policy', 'What type of accommodation and how many per room, separated how?', 'Fully Funded covers accommodation. No standard is published.', 'Accommodation is likely the largest cost line and a major part of the participant and parent experience.', 'None.', null, '[{"key": "A", "label": "Hostel/dorm-style, 4–6 per room", "summary": "", "pros": "Lowest cost.", "cons": "Less privacy; harder for minors'' separation.", "cost": "", "operations": "", "participant": "", "fact_updates": {}}, {"key": "B", "label": "Budget hotel, 3–4 per room", "summary": "", "pros": "Balance of cost and safety.", "cons": "", "cost": "", "operations": "", "participant": "", "fact_updates": {}}, {"key": "C", "label": "Hotel, twin rooms", "summary": "", "pros": "Comfort.", "cons": "Highest cost.", "cost": "", "operations": "", "participant": "", "fact_updates": {}}]'::jsonb, 'B', 'B, gender-separated, minors roomed only with minors of the same gender, staff rooms on the same floor. Confirm with quotes (GIF-RES-008).', 'GIF-RES-008.', 'No accommodation quotes, no budget.', 'Research: GIF-RES-008; Tasks: GIF-T-063', 'High', 'Travel and accommodation preparation', '2027-01-31', 'Quotes needed for G2.', (select id from public.os_people where id = 'PPL-0002'), 'Pending Decision', 140) on conflict (code) do nothing;
  insert into public.os_programme_decisions (project_id, code, title, question, background, why_it_matters, current_situation, evidence, options, recommended_option, recommendation, info_needed, delay_consequence, dependencies, priority, phase, suggested_deadline, deadline_basis, owner_person_id, status, sort) values (v_prj, 'GIF-DEC-016', 'Choose the local support model in each country', 'Who executes on the ground in Singapore, Malaysia and Thailand?', 'Only 8 core staff travel. Local support has not been approached anywhere.', 'Without local support the 8 must do registration, transport coordination, translation and setup themselves.', 'None.', null, '[{"key": "A", "label": "Paid local coordinator per country + volunteers", "summary": "One paid coordinator (or DMC) per country plus 4–8 volunteers from Indonesian student associations and host-university student organisations.", "pros": "Accountable local lead; volunteers for non-sensitive tasks.", "cons": "Coordinator fees.", "cost": "3 coordinator fees (quotes)", "operations": "", "participant": "", "fact_updates": {}}, {"key": "B", "label": "Volunteers only", "summary": "", "pros": "Lowest cost.", "cons": "No accountable local lead; reliability risk.", "cost": "", "operations": "", "participant": "", "fact_updates": {}}, {"key": "C", "label": "Destination management company (DMC) per country", "summary": "", "pros": "Handles transport, venues, guides.", "cons": "Highest cost; less control.", "cost": "", "operations": "", "participant": "", "fact_updates": {}}]'::jsonb, 'A', 'A. Volunteers never handle money, medical information, minors alone or institutional commitments; each country has one core supervisor (Country lead).', 'Availability and rates of local coordinators (GIF-RES-022); student organisations'' interest (GIF-T-071).', 'Local recruitment needs 4–6 months; leaving it late concentrates all work on the 8.', 'Research: GIF-RES-022, GIF-RES-023; Tasks: GIF-T-070, GIF-T-071, GIF-T-072', 'High', 'Local volunteer recruitment', '2027-01-15', 'Outreach to local groups starts in January.', (select id from public.os_people where id = 'PPL-0002'), 'Pending Decision', 150) on conflict (code) do nothing;
  insert into public.os_programme_decisions (project_id, code, title, question, background, why_it_matters, current_situation, evidence, options, recommended_option, recommendation, info_needed, delay_consequence, dependencies, priority, phase, suggested_deadline, deadline_basis, owner_person_id, status, sort) values (v_prj, 'GIF-DEC-017', 'Decide volunteer incentives and what IELSco covers for them', 'What do local volunteers receive (meals, transport, certificate, kit, allowance)?', 'Local support is not free by default.', 'Affects recruitment of volunteers and the budget.', 'None.', null, '[{"key": "A", "label": "Meals, local transport, certificate, kit", "summary": "", "pros": "", "cons": "", "cost": "", "operations": "", "participant": "", "fact_updates": {}}, {"key": "B", "label": "As A plus a small daily allowance", "summary": "", "pros": "Better reliability.", "cons": "Cost; may create employment questions locally.", "cost": "", "operations": "", "participant": "", "fact_updates": {}}, {"key": "C", "label": "Certificate only", "summary": "", "pros": "Cheapest.", "cons": "Few volunteers.", "cost": "", "operations": "", "participant": "", "fact_updates": {}}]'::jsonb, 'A', 'A, and ask local counsel or the host organisation whether any allowance creates obligations (GIF-RES-024).', 'GIF-RES-024.', 'Can''t recruit volunteers.', 'Research: GIF-RES-024; Tasks: GIF-T-073', 'Medium', 'Local volunteer recruitment', '2027-03-01', 'Before volunteer recruitment opens.', (select id from public.os_people where id = 'PPL-0002'), 'Pending Decision', 160) on conflict (code) do nothing;
  insert into public.os_programme_decisions (project_id, code, title, question, background, why_it_matters, current_situation, evidence, options, recommended_option, recommendation, info_needed, delay_consequence, dependencies, priority, phase, suggested_deadline, deadline_basis, owner_person_id, status, sort) values (v_prj, 'GIF-DEC-018', 'Approve the institutional outreach approach', 'Which universities do we approach, through which offices, for what (visit, session, co-hosted event), and who signs?', 'No institution has confirmed anything. Shafira''s TSK-0107 (research NUS, UTM, Chulalongkorn) is due 18 Dec. The website names NUS, UM and Chulalongkorn as ''planned''.', 'Institutional engagement is a core participant promise and the hardest external dependency.', 'Research stage.', null, '[{"key": "A", "label": "One ask per university: a hosted campus session, through the international/outreach office", "summary": "Letter signed by Arba; Shafira coordinates.", "pros": "Clear, modest ask.", "cons": "", "cost": "", "operations": "", "participant": "", "fact_updates": {}}, {"key": "B", "label": "Broader partnership (MoU) asks", "summary": "", "pros": "Longer-term value.", "cons": "Slow; legal review on both sides; unlikely by July.", "cost": "", "operations": "", "participant": "", "fact_updates": {}}]'::jsonb, 'A', 'A: a modest, specific ask per university, with an MoU only if the institution proposes one.', 'TSK-0107 findings.', 'Outreach slips past January; hosts'' calendars fill.', 'Tasks: GIF-T-040, GIF-T-041, GIF-T-042', 'High', 'Partner engagement', '2026-12-18', 'Outreach letters go out in January.', (select id from public.os_people where id = 'PPL-0001'), 'Pending Decision', 170) on conflict (code) do nothing;
  insert into public.os_programme_decisions (project_id, code, title, question, background, why_it_matters, current_situation, evidence, options, recommended_option, recommendation, info_needed, delay_consequence, dependencies, priority, phase, suggested_deadline, deadline_basis, owner_person_id, status, sort) values (v_prj, 'GIF-DEC-019', 'Decide how the website names the universities until confirmed', 'Keep naming NUS, Universiti Malaya and Chulalongkorn as ''planned visits'' on gif.ielsco.com, or remove the names until written confirmation?', 'The site shows ''Planned visits to NUS, Universiti Malaya and Chulalongkorn (status shown below)''. DOC-0053''s brand rule says never name them as partners before written evidence. ''Planned'' is not ''partner'', but it still sets expectations.', 'Reputational and consumer-protection risk if a visit doesn''t happen.', 'Live with ''planned'' status labels.', null, '[{"key": "A", "label": "Keep, with explicit ''subject to confirmation'' wording and no logos", "summary": "", "pros": "Keeps marketing appeal; honest.", "cons": "Some risk if a visit falls through.", "cost": "", "operations": "Small copy change", "participant": "", "fact_updates": {}}, {"key": "B", "label": "Remove names until written confirmation", "summary": "", "pros": "Zero overclaim risk.", "cons": "Less attractive marketing now.", "cost": "", "operations": "Copy change", "participant": "", "fact_updates": {}}, {"key": "C", "label": "Keep as is", "summary": "", "pros": "", "cons": "", "cost": "", "operations": "", "participant": "", "fact_updates": {}}]'::jsonb, 'A', 'A: keep the names only as ''planned, subject to confirmation'', no logos or ''in partnership with'', and add the same sentence to the FAQ and terms. Prepared as a draft change for review; not deployed.', 'None.', 'Expectations harden as more people register.', 'Tasks: GIF-T-021', 'Critical', 'Recruitment preparation', '2026-11-28', 'Recruitment traffic is rising with Fully Funded opening on 25 Nov.', (select id from public.os_people where id = 'PPL-0001'), 'Pending Decision', 180) on conflict (code) do nothing;
  insert into public.os_programme_decisions (project_id, code, title, question, background, why_it_matters, current_situation, evidence, options, recommended_option, recommendation, info_needed, delay_consequence, dependencies, priority, phase, suggested_deadline, deadline_basis, owner_person_id, status, sort) values (v_prj, 'GIF-DEC-020', 'Define the conference, competition and awarding format', 'What is the pitching competition (who competes, judged how, what awards), and is the conference a separate event?', 'The objectives include project mentoring, pitching, conference, competition and awarding. No format, judges, awards or venue exist.', 'Shapes the programme design, judges, venue size, AV and certificates.', 'None.', null, '[{"key": "A", "label": "Team pitching competition on the final full day, external judges, non-cash awards", "summary": "", "pros": "Simple; one big venue day.", "cons": "", "cost": "Venue + AV", "operations": "", "participant": "", "fact_updates": {}}, {"key": "B", "label": "Heats in each country, final in Bangkok", "summary": "", "pros": "Engagement across the route.", "cons": "Three venue setups.", "cost": "", "operations": "", "participant": "", "fact_updates": {}}, {"key": "C", "label": "Conference + pitching combined, co-hosted with a university", "summary": "", "pros": "Prestige.", "cons": "Depends on a host.", "cost": "", "operations": "", "participant": "", "fact_updates": {}}]'::jsonb, 'A', 'A as the base, upgrading to C only if a host confirms in writing.', 'Venue options (GIF-RES-020).', 'Judges and venues get booked by others.', 'Research: GIF-RES-020; Tasks: GIF-T-051, GIF-T-052, GIF-T-090', 'Medium', 'Programme design', '2027-02-26', 'Before venue research and judge outreach.', (select id from public.os_people where id = 'PPL-0001'), 'Pending Decision', 190) on conflict (code) do nothing;
  insert into public.os_programme_decisions (project_id, code, title, question, background, why_it_matters, current_situation, evidence, options, recommended_option, recommendation, info_needed, delay_consequence, dependencies, priority, phase, suggested_deadline, deadline_basis, owner_person_id, status, sort) values (v_prj, 'GIF-DEC-021', 'Decide how Project Mentoring is delivered', 'Who mentors, how many sessions, online or in person, and are mentors paid?', 'Mentoring is sold now (Early Bird to 31 Dec) with sessions 2 Feb – 11 May. Mentor profiles are placeholders (DECISIONS.md open item 10).', 'Paying customers expect named mentors and a schedule; refunds depend on Session 4 timing.', 'Selling without confirmed mentors.', null, '[{"key": "A", "label": "Online cohort sessions with 2–4 recruited mentors (honorarium)", "summary": "", "pros": "Scalable; schedule fixed now.", "cons": "Mentor fees.", "cost": "", "operations": "", "participant": "", "fact_updates": {}}, {"key": "B", "label": "Core team mentors", "summary": "", "pros": "No cost.", "cons": "Adds load to managers capped at 10 h/week.", "cost": "", "operations": "", "participant": "", "fact_updates": {}}, {"key": "C", "label": "Volunteer mentors from partner networks", "summary": "", "pros": "No cost.", "cons": "Reliability.", "cost": "", "operations": "", "participant": "", "fact_updates": {}}]'::jsonb, 'A', 'A: recruit 2–4 mentors with written agreements by 15 Jan; publish the session schedule before the Early Bird ends if possible.', 'Mentor candidates and fees (GIF-T-053).', 'Customers may ask for refunds; credibility.', 'Tasks: GIF-T-053, GIF-T-054', 'High', 'Programme design', '2026-12-31', 'Sessions start 2 Feb 2027.', (select id from public.os_people where id = 'PPL-0001'), 'Pending Decision', 200) on conflict (code) do nothing;
  insert into public.os_programme_decisions (project_id, code, title, question, background, why_it_matters, current_situation, evidence, options, recommended_option, recommendation, info_needed, delay_consequence, dependencies, priority, phase, suggested_deadline, deadline_basis, owner_person_id, status, sort) values (v_prj, 'GIF-DEC-023', 'Confirm cashback payment timing', 'When is the mentoring cashback paid after a Fully/Partial Funded result is verified?', 'Site and Mentoring Terms say ''within 30 days of verification'', bracketed as a proposal.', 'Payment promise in legal text.', 'Proposed.', null, '[{"key": "A", "label": "Within 30 days of verification", "summary": "", "pros": "", "cons": "", "cost": "", "operations": "", "participant": "", "fact_updates": {"payments.cashback_timing": "Within 30 days of verification"}}, {"key": "B", "label": "Within 14 days", "summary": "", "pros": "", "cons": "", "cost": "", "operations": "", "participant": "", "fact_updates": {"payments.cashback_timing": "Within 14 days of verification"}}]'::jsonb, 'A', 'A, as already drafted.', 'None.', 'Bracketed legal text.', null, 'Medium', 'Financial preparation', '2026-12-31', 'Mentoring Terms need final text before counsel review.', (select id from public.os_people where id = 'PPL-0001'), 'Pending Decision', 210) on conflict (code) do nothing;
  insert into public.os_programme_decisions (project_id, code, title, question, background, why_it_matters, current_situation, evidence, options, recommended_option, recommendation, info_needed, delay_consequence, dependencies, priority, phase, suggested_deadline, deadline_basis, owner_person_id, status, sort) values (v_prj, 'GIF-DEC-024', 'Fill in the bracketed legal values', 'Refund processing time, data retention periods and the dispute forum in the legal drafts.', 'Proposed values are in [brackets] in the legal drafts (DECISIONS.md open item 6).', 'Counsel needs final instructions.', 'Bracketed.', null, '[{"key": "A", "label": "Accept the proposed values for counsel review", "summary": "", "pros": "Fast.", "cons": "", "cost": "", "operations": "", "participant": "", "fact_updates": {}}, {"key": "B", "label": "Change values", "summary": "", "pros": "", "cons": "", "cost": "", "operations": "", "participant": "", "fact_updates": {}}]'::jsonb, 'A', 'A, then let counsel change them if needed.', 'Counsel.', 'Counsel review can''t finish.', 'Tasks: GIF-T-030', 'High', 'Research and decision-making', '2026-12-15', 'Before counsel review (GIF-DEC-025).', (select id from public.os_people where id = 'PPL-0001'), 'Pending Decision', 220) on conflict (code) do nothing;
  insert into public.os_programme_decisions (project_id, code, title, question, background, why_it_matters, current_situation, evidence, options, recommended_option, recommendation, info_needed, delay_consequence, dependencies, priority, phase, suggested_deadline, deadline_basis, owner_person_id, status, sort) values (v_prj, 'GIF-DEC-025', 'Commission counsel review of the participant legal documents', 'Who reviews the 10 legal drafts, by when, and with what budget?', 'All 10 GIF legal documents are drafts marked ''Draf untuk ditinjau penasihat hukum''. Participants are paying under them now.', 'Payment, refund, liability, privacy and minors'' consent terms must be enforceable.', 'Not commissioned.', null, '[{"key": "A", "label": "Indonesian counsel now, full set", "summary": "", "pros": "Covers PT IELSco and UU PDP.", "cons": "Fees.", "cost": "Counsel fee (quote)", "operations": "", "participant": "", "fact_updates": {}}, {"key": "B", "label": "Counsel for payment/refund/privacy/minors first, rest later", "summary": "", "pros": "Prioritises live risk.", "cons": "Two rounds.", "cost": "", "operations": "", "participant": "", "fact_updates": {}}]'::jsonb, 'B', 'B: commission Indonesian counsel this month for the four live-risk documents (Payment Terms, Refund Policy, Privacy Policy, Parental Consent), the rest by February.', 'Counsel quotes.', 'Participants pay under unreviewed terms.', 'Tasks: GIF-T-030, GIF-T-031', 'Critical', 'Research and decision-making', '2026-12-05', 'Payments are live.', (select id from public.os_people where id = 'PPL-0001'), 'Pending Decision', 230) on conflict (code) do nothing;
  insert into public.os_programme_decisions (project_id, code, title, question, background, why_it_matters, current_situation, evidence, options, recommended_option, recommendation, info_needed, delay_consequence, dependencies, priority, phase, suggested_deadline, deadline_basis, owner_person_id, status, sort) values (v_prj, 'GIF-DEC-026', 'Set the recruitment post for the Phase 1 social tasks', 'Which Instagram post do applicants like, comment on and share?', 'Fully Funded opens 25 Nov. Phase 1 includes 5 verified social tasks; 3 of them link to a recruitment post whose URL is not set (links point to @iels.co).', 'Applicants can''t complete Phase 1 tasks correctly; staff can''t verify them consistently.', 'Not set.', null, '[{"key": "A", "label": "Publish the post by 24 Nov and set the URL", "summary": "", "pros": "Tasks work from day one.", "cons": "Tight.", "cost": "", "operations": "Settings change (Admin → Content)", "participant": "", "fact_updates": {}}, {"key": "B", "label": "Hide the 3 post tasks until the post exists", "summary": "", "pros": "No broken tasks.", "cons": "Later applicants have different tasks.", "cost": "", "operations": "", "participant": "", "fact_updates": {}}]'::jsonb, 'A', 'A: Acha publishes the post, Didi sets `instagram.recruitment_post` in GIF Admin before 25 Nov.', 'None.', 'Broken Phase 1 instructions on launch day.', 'Tasks: GIF-T-022', 'Critical', 'Recruitment and admissions', '2026-11-24', 'Fully Funded opens 25 Nov 00:00 WIB.', (select id from public.os_people where id = 'PPL-0003'), 'Pending Decision', 240) on conflict (code) do nothing;
  insert into public.os_programme_decisions (project_id, code, title, question, background, why_it_matters, current_situation, evidence, options, recommended_option, recommendation, info_needed, delay_consequence, dependencies, priority, phase, suggested_deadline, deadline_basis, owner_person_id, status, sort) values (v_prj, 'GIF-DEC-027', 'Choose the bank account for invoice payments', 'Which account receives USD invoice payments?', 'Invoice bank details are empty in the GIF engine; the code comment says Finance may designate a personal account.', 'IELSco and Elco must keep separate records; personal accounts break auditability.', 'Not entered.', null, '[{"key": "A", "label": "A PT IELSco company account (USD or IDR)", "summary": "", "pros": "Auditable; separate entity.", "cons": "May need a USD account or conversion.", "cost": "", "operations": "", "participant": "", "fact_updates": {}}, {"key": "B", "label": "Designated personal account", "summary": "", "pros": "Quick.", "cons": "Commingling; audit and tax risk.", "cost": "", "operations": "", "participant": "", "fact_updates": {}}]'::jsonb, 'A', 'A. If PT IELSco has no USD account, receive IDR at the published card rate or open one; avoid personal accounts.', 'Bank account options (GIF-RES-026).', 'International participants can''t pay by invoice.', 'Research: GIF-RES-026; Tasks: GIF-T-013', 'High', 'Financial preparation', '2026-11-30', 'International registrations are open.', (select id from public.os_people where id = 'PPL-0001'), 'Pending Decision', 250) on conflict (code) do nothing;
  insert into public.os_programme_decisions (project_id, code, title, question, background, why_it_matters, current_situation, evidence, options, recommended_option, recommendation, info_needed, delay_consequence, dependencies, priority, phase, suggested_deadline, deadline_basis, owner_person_id, status, sort) values (v_prj, 'GIF-DEC-028', 'Approve the selection committee and rubric', 'Who evaluates Phase 2 and 3, with what rubric, and how are conflicts of interest handled?', 'Evaluator roles exist in the GIF engine; no rubric or committee is on record.', 'Fairness and defensibility of Fully Funded awards.', 'Not set.', null, '[{"key": "A", "label": "Arba, Farrel + 2 managers, written rubric, declared conflicts", "summary": "", "pros": "", "cons": "Load on managers in May.", "cost": "", "operations": "", "participant": "", "fact_updates": {}}, {"key": "B", "label": "Add 1–2 external evaluators", "summary": "", "pros": "Independence.", "cons": "Coordination.", "cost": "", "operations": "", "participant": "", "fact_updates": {}}]'::jsonb, 'B', 'B: the rubric is published in summary in the Selection Terms; each application scored by two evaluators.', 'None.', 'Phase 2 opens 11 May.', 'Tasks: GIF-T-024, GIF-T-025', 'High', 'Recruitment and admissions', '2027-04-15', 'Four weeks before Phase 2.', (select id from public.os_people where id = 'PPL-0002'), 'Pending Decision', 260) on conflict (code) do nothing;
  insert into public.os_programme_decisions (project_id, code, title, question, background, why_it_matters, current_situation, evidence, options, recommended_option, recommendation, info_needed, delay_consequence, dependencies, priority, phase, suggested_deadline, deadline_basis, owner_person_id, status, sort) values (v_prj, 'GIF-DEC-029', 'Set waitlist, withdrawal and seat-release rules', 'What happens when Self-Funded fills, and when someone withdraws?', 'Self-Funded is ''subject to capacity''.', 'Capacity and refund exposure.', 'Not set.', null, '[{"key": "A", "label": "Waitlist with 7-day offer windows", "summary": "", "pros": "", "cons": "", "cost": "", "operations": "", "participant": "", "fact_updates": {}}, {"key": "B", "label": "No waitlist", "summary": "", "pros": "", "cons": "", "cost": "", "operations": "", "participant": "", "fact_updates": {}}]'::jsonb, 'A', 'A.', 'None.', 'Over-booking or unused places.', 'Tasks: GIF-T-026', 'Medium', 'Recruitment and admissions', '2027-03-31', 'Before Self-Funded could fill.', (select id from public.os_people where id = 'PPL-0003'), 'Pending Decision', 270) on conflict (code) do nothing;
  insert into public.os_programme_decisions (project_id, code, title, question, background, why_it_matters, current_situation, evidence, options, recommended_option, recommendation, info_needed, delay_consequence, dependencies, priority, phase, suggested_deadline, deadline_basis, owner_person_id, status, sort) values (v_prj, 'GIF-DEC-031', 'Decide photo and video coverage', 'In-house (Mojo and volunteers) or a hired local photographer/videographer per country?', 'Media consent is part of the legal set (draft).', 'Impact report, social content, future marketing.', 'None.', null, '[{"key": "A", "label": "Mojo leads, 1 trained volunteer per country", "summary": "", "pros": "Low cost.", "cons": "Mojo can''t also run stage visuals.", "cost": "", "operations": "", "participant": "", "fact_updates": {}}, {"key": "B", "label": "Hire a local photographer for the conference/awarding day only", "summary": "", "pros": "Quality where it matters.", "cons": "Fee.", "cost": "", "operations": "", "participant": "", "fact_updates": {}}]'::jsonb, 'B', 'B plus A for other days.', 'Quotes.', 'Booking late.', 'Tasks: GIF-T-091', 'Medium', 'Programme design', '2027-04-30', 'Before vendor bookings.', (select id from public.os_people where id = 'PPL-0005'), 'Pending Decision', 280) on conflict (code) do nothing;
