  insert into public.os_programme_decisions (project_id, code, title, question, background, why_it_matters, current_situation, evidence, options, recommended_option, recommendation, info_needed, delay_consequence, dependencies, priority, phase, suggested_deadline, deadline_basis, owner_person_id, status, sort) values (v_prj, 'GIF-DEC-033', 'Decide certificate and award wording', 'IELSco-only certificates, or co-branded with institutions?', 'DOC-0054: co-branding only with written permission.', 'Overclaim risk.', 'None.', null, '[{"key": "A", "label": "IELSco certificates; partner mention only with written permission", "summary": "", "pros": "", "cons": "", "cost": "", "operations": "", "participant": "", "fact_updates": {}}, {"key": "B", "label": "Co-branded", "summary": "", "pros": "", "cons": "Needs each institution''s written approval.", "cost": "", "operations": "", "participant": "", "fact_updates": {}}]'::jsonb, 'A', 'A.', 'None.', 'Printing deadline.', 'Tasks: GIF-T-090', 'Medium', 'Programme design', '2027-05-31', 'Printing in June.', (select id from public.os_people where id = 'PPL-0001'), 'Pending Decision', 300) on conflict (code) do nothing;
