  insert into public.os_programme_decisions (project_id, code, title, question, background, why_it_matters, current_situation, evidence, options, recommended_option, recommendation, info_needed, delay_consequence, dependencies, priority, phase, suggested_deadline, deadline_basis, owner_person_id, status, sort) values (v_prj, 'GIF-DEC-035', 'Confirm the visa support policy', 'What visa help does IELSco give (invitation letters, itineraries), and for whom?', 'Site: participants are responsible; IELSco provides supporting documents. International participants may need visas for some of the three countries.', 'Visa refusal is a refund trigger and a participant-experience risk.', 'Proposed.', null, '[{"key": "A", "label": "Supporting letter + itinerary on request; no guarantee", "summary": "", "pros": "", "cons": "", "cost": "", "operations": "", "participant": "", "fact_updates": {"visa.policy": "Participants are responsible; IELSco issues a supporting letter and itinerary on request"}}, {"key": "B", "label": "Restrict international admissions to visa-exempt nationalities", "summary": "", "pros": "Fewer refusals.", "cons": "Smaller market.", "cost": "", "operations": "", "participant": "", "fact_updates": {}}]'::jsonb, 'A', 'A, plus an application-time nationality check so participants see visa needs before paying (GIF-RES-002).', 'GIF-RES-001, GIF-RES-002.', 'Late visa refusals and refunds.', 'Research: GIF-RES-001, GIF-RES-002; Tasks: GIF-T-064', 'Medium', 'Research and decision-making', '2027-02-26', 'International recruitment is open.', (select id from public.os_people where id = 'PPL-0002'), 'Pending Decision', 320) on conflict (code) do nothing;
  insert into public.os_programme_decisions (project_id, code, title, question, background, why_it_matters, current_situation, evidence, options, recommended_option, recommendation, info_needed, delay_consequence, dependencies, priority, phase, suggested_deadline, deadline_basis, owner_person_id, status, sort) values (v_prj, 'GIF-DEC-037', 'Confirm the consent basis for Elco Pro data', 'What personal data passes from GIF to PT Elco for Elco Pro, and under what consent?', 'Elco Pro is a Fully Funded Phase 1 requirement, fulfilled manually by Finance until the Elco API exists. DOC-0053: no automatic data sharing between PT IELSco and PT Elco.', 'Two separate PTs; UU PDP compliance.', 'Manual fulfilment; consent wording not reviewed.', null, '[{"key": "A", "label": "Explicit consent at purchase; only name + email passed", "summary": "", "pros": "", "cons": "", "cost": "", "operations": "", "participant": "", "fact_updates": {}}, {"key": "B", "label": "Applicant activates Elco Pro themselves with a code", "summary": "", "pros": "No data transfer.", "cons": "Extra step.", "cost": "", "operations": "", "participant": "", "fact_updates": {}}]'::jsonb, 'B', 'B if Elco can issue codes; otherwise A, reviewed by counsel.', 'Elco grant endpoint status (GIF-RES-027).', 'Compliance risk.', 'Research: GIF-RES-027; Tasks: GIF-T-032', 'High', 'Research and decision-making', '2026-12-15', 'Fully Funded opens 25 Nov.', (select id from public.os_people where id = 'PPL-0001'), 'Pending Decision', 330) on conflict (code) do nothing;
  insert into public.os_programme_decisions (project_id, code, title, question, background, why_it_matters, current_situation, evidence, options, recommended_option, recommendation, info_needed, delay_consequence, dependencies, priority, phase, suggested_deadline, deadline_basis, owner_person_id, status, sort) values (v_prj, 'GIF-DEC-038', 'Set success criteria and KPIs', 'What will count as success for GIF 2027?', 'KPI definitions exist (KPI-0059 to KPI-0068) with no targets.', 'Evaluation design and the impact report.', 'No targets.', null, '[{"key": "A", "label": "Approve the KPI set in this workspace with targets set at G2", "summary": "", "pros": "", "cons": "", "cost": "", "operations": "", "participant": "", "fact_updates": {}}, {"key": "B", "label": "Definitions only, no targets", "summary": "", "pros": "", "cons": "", "cost": "", "operations": "", "participant": "", "fact_updates": {}}]'::jsonb, 'A', 'A.', 'Baseline data from the GIF engine.', 'Evaluation designed after the fact.', 'Tasks: GIF-T-110', 'Medium', 'Initial planning', '2027-01-15', 'Surveys must be designed before the programme.', (select id from public.os_people where id = 'PPL-0002'), 'Pending Decision', 340) on conflict (code) do nothing;
