  insert into public.os_programme_findings (project_id, code, title, detail, evidence, severity, proposed_action, decision_code, sort) values (v_prj, 'GIF-FND-001', 'Two GIF timelines with different programme dates', 'DOC-0054 and 52 GIF rows on the Master Timeline (TL-020 to TL-104) use a 7-day programme on 5–11 Jul 2027 with applications from 26 Apr 2027. The platform and founder decisions use 27 Jul – 3 Aug 2027 with registration since 20 Nov 2026.', 'DOC-0054 §2; os_timeline_items TL-051 ''GIF 2027 event (seven days)'' due 2027-07-11; apps/gif settings dates; gif.cohorts summer-2027', 'High', 'Mark old rows Cancelled with a pointer to WS10 (GIF-DEC-009).', 'GIF-DEC-009', 0) on conflict (code) do nothing;
  insert into public.os_programme_findings (project_id, code, title, detail, evidence, severity, proposed_action, decision_code, sort) values (v_prj, 'GIF-FND-002', 'Malaysia city conflict: Johor Bahru (UTM) vs Kuala Lumpur (Universiti Malaya)', 'DOC-0054 plans UTM Johor Bahru; the website and engine settings list Universiti Malaya (Kuala Lumpur); UTM is not on the website.', 'DOC-0054 §2; apps/gif/src/lib/settings.ts universities[]', 'High', 'Decide the city (GIF-DEC-002).', 'GIF-DEC-002', 10) on conflict (code) do nothing;
  insert into public.os_programme_findings (project_id, code, title, detail, evidence, severity, proposed_action, decision_code, sort) values (v_prj, 'GIF-FND-003', 'Deposit task conflicts with the platform', 'PRJ-0033 has ''Secure USD 1,500 participant deposits'' (TSK-0113, Arba, Ready, due 13 Nov, overdue; duplicate TSK-0122 cancelled). The engine charges USD 300 / IDR 5,000,000, itself unconfirmed.', 'os_tasks TSK-0113; apps/gif settings prices.self_funded_deposit', 'High', 'Close or rewrite TSK-0113 after GIF-DEC-001.', 'GIF-DEC-001', 20) on conflict (code) do nothing;
  insert into public.os_programme_findings (project_id, code, title, detail, evidence, severity, proposed_action, decision_code, sort) values (v_prj, 'GIF-FND-004', 'Launch calendar events predate the live opening', 'EV-0032 ''GIF 2027 Open Pre-Launch'' (7 Dec 2026) and EV-0033 ''GIF 2027 Official Launch'' (9 Jan 2027) vs Self-Funded/Mentoring open 20 Nov and Fully Funded 25 Nov 2026.', 'os_events EV-0032, EV-0033; docs/gif-platform/IELSCO-INTEGRATION.md §4', 'Medium', 'Repurpose the events (GIF-DEC-010).', 'GIF-DEC-010', 30) on conflict (code) do nothing;
  insert into public.os_programme_findings (project_id, code, title, detail, evidence, severity, proposed_action, decision_code, sort) values (v_prj, 'GIF-FND-005', 'Vague and overdue PRJ-0033 tasks', 'TSK-0112 ''Follow up sales prospects'' (Arba, due 13 Nov) has no definition of done; TSK-0114/0115 overdue since 13 Nov. Cancelled duplicates TSK-0121 to TSK-0127 exist.', 'os_tasks', 'Low', 'Rewrite TSK-0112 as specific sponsor or partner tasks, or cancel; re-date TSK-0114/0115 (adopted as GIF-T-007/006).', null, 40) on conflict (code) do nothing;
  insert into public.os_programme_findings (project_id, code, title, detail, evidence, severity, proposed_action, decision_code, sort) values (v_prj, 'GIF-FND-006', 'Yasmine has the founder role in Company OS', 'os_people PPL-0006 (Nashwa Maulida Yasmine, People Manager) has org_role ''founder'', which gives access to every record including Restricted finance and legal. DOC-0053 lists two founders (Arba, Farrel). Her manager agreement is a manager engagement.', 'os_people PPL-0006; DOC-0053 §2; manager agreement', 'High', 'Founder to confirm; if unintended, change her role to manager in Admin → People (an access change: needs Arba''s OK).', null, 50) on conflict (code) do nothing;
  insert into public.os_programme_findings (project_id, code, title, detail, evidence, severity, proposed_action, decision_code, sort) values (v_prj, 'GIF-FND-007', 'Marketing division not in the Company OS', 'Acha''s agreement is for a Marketing division; in the OS she is a non-manager member of Growth (DIV-03). DOC-0053 had no Marketing division.', 'os_person_divisions; manager agreement (Marketing)', 'Medium', 'Founder to decide whether Marketing becomes a division or stays inside Growth. GIF assigns Acha by name either way.', null, 60) on conflict (code) do nothing;
  insert into public.os_programme_findings (project_id, code, title, detail, evidence, severity, proposed_action, decision_code, sort) values (v_prj, 'GIF-FND-008', 'Role names differ between DOC-0053 and the current directory', 'DOC-0053 (26 Oct) has Shafira as People, Operations and Partnerships vacant. The OS directory (Nov) has Shafira as Partnership Manager, Yasmine as People Manager, Renita as Operations Manager, Acha as Marketing Manager. The directory and the agreements are newer.', 'DOC-0053 §2 vs os_people/os_person_profiles', 'Medium', 'Treat the directory as current; update DOC-0053 when it is next revised.', null, 70) on conflict (code) do nothing;
  insert into public.os_programme_findings (project_id, code, title, detail, evidence, severity, proposed_action, decision_code, sort) values (v_prj, 'GIF-FND-009', 'Meals are not in the Fully Funded cover', 'Fully Funded covers programme fee, accommodation and in-programme transportation. Meals are not mentioned anywhere public.', 'apps/gif settings awards; founder brief', 'Medium', 'Decide whether meals are in the programme fee and say so on the site and in the handbook.', null, 80) on conflict (code) do nothing;
  insert into public.os_programme_findings (project_id, code, title, detail, evidence, severity, proposed_action, decision_code, sort) values (v_prj, 'GIF-FND-010', 'UTM missing from the website university list', 'The founder brief and DOC-0054 include UTM; the site lists NUS, UM and Chulalongkorn only.', 'apps/gif settings universities[]', 'Low', 'Resolved by GIF-DEC-002/019.', 'GIF-DEC-019', 90) on conflict (code) do nothing;
  insert into public.os_programme_findings (project_id, code, title, detail, evidence, severity, proposed_action, decision_code, sort) values (v_prj, 'GIF-FND-011', 'Company OS project PRJ-0033 has no description or definition of done', 'The GIF project exists (Active, owner Arba, Operations) with no description, success metric or definition of done.', 'os_projects PRJ-0033', 'Low', 'Fill from the Facts tab once GIF-DEC-038 is decided.', 'GIF-DEC-038', 100) on conflict (code) do nothing;
  insert into public.os_programme_findings (project_id, code, title, detail, evidence, severity, proposed_action, decision_code, sort) values (v_prj, 'GIF-FND-012', 'Master Timeline links GIF to G0–G5 gates on the old dates', 'Gate items TL-024 (G1, 12 Mar), TL-029 (G0, 15 Jan), TL-036 (G3, 23 Apr), TL-046 (G4, 1 Jun), TL-049 (G5, 25 Jun).', 'os_timeline_items', 'Medium', 'Re-dated gates in WS10 (GIF-DEC-040).', 'GIF-DEC-040', 110) on conflict (code) do nothing;
